    def list_audit_logs(
        self,
        project_id: str,
        *,
        credential_id: str | None = None,
        event: str | None = None,
        decision: AuditDecision | None = None,
        source: AuditSource | None = None,
        start: str | None = None,
        end: str | None = None,
        before: str | None = None,
        page_size: int | None = None,
        page_token: str | None = None,
    ) -> ListAuditLogsResponse:
        """List agent audit logs.

        Returns agent statement audit entries for the project, newest first, with optional credential, event, decision, source and date-range filters.

        ``GET /v1/projects/{project_id}/audit-logs``

        Args:
            project_id: Unique project identifier (prefixed, e.g. prj_xxx).
            credential_id: Filter to a single agent credential.
            event: Filter to a single event type (e.g. blocked, masked, query).
            decision: Coarse outcome filter that groups events. `allow` = query, auto_approved; `block` = blocked, budget_exhausted, auth_failed, credential_expired, canary_tripped, rejected, approval_expired; `mask` = masked; `truncate` = truncated.
            source: Filter by statement origin (wire, mcp, rest, or control).
            start: Return entries at or after this timestamp (inclusive lower bound).
            end: Return entries strictly older than this timestamp (cursor / upper bound).
            before: Return entries strictly older than this timestamp (keyset pagination cursor).
            page_size: Maximum number of items to return (1-100, default 20).
            page_token: Opaque token for cursor-based pagination.
        """
        return cast(
            ListAuditLogsResponse,
            self._transport.request(
                "GET",
                "/v1/projects/{project_id}/audit-logs",
                path_params={
                    "project_id": project_id,
                },
                query={
                    "credential_id": credential_id,
                    "event": event,
                    "decision": decision,
                    "source": source,
                    "start": start,
                    "end": end,
                    "before": before,
                    "page_size": page_size,
                    "page_token": page_token,
                },
            ),
        )

    def export_audit_logs(
        self,
        project_id: str,
        *,
        credential_id: str | None = None,
        event: str | None = None,
        decision: AuditDecision | None = None,
        source: AuditSource | None = None,
        start: str | None = None,
        end: str | None = None,
    ) -> str:
        """Export agent audit logs as CSV.

        Streams the project's agent audit entries as a CSV file, newest first, honoring the same credential, event, decision, source and date-range filters as the list endpoint. The full filtered set is streamed (no pagination); the result is suitable for spreadsheets, SIEM ingestion, and compliance archives.

        ``GET /v1/projects/{project_id}/audit-logs/export``

        Args:
            project_id: Unique project identifier (prefixed, e.g. prj_xxx).
            credential_id: Filter to a single agent credential.
            event: Filter to a single event type (e.g. blocked, masked, query).
            decision: Coarse outcome filter that groups events. `allow` = query, auto_approved; `block` = blocked, budget_exhausted, auth_failed, credential_expired, canary_tripped, rejected, approval_expired; `mask` = masked; `truncate` = truncated.
            source: Filter by statement origin (wire, mcp, rest, or control).
            start: Return entries at or after this timestamp (inclusive lower bound).
            end: Return entries strictly older than this timestamp (cursor / upper bound).
        """
        return cast(
            str,
            self._transport.request(
                "GET",
                "/v1/projects/{project_id}/audit-logs/export",
                path_params={
                    "project_id": project_id,
                },
                query={
                    "credential_id": credential_id,
                    "event": event,
                    "decision": decision,
                    "source": source,
                    "start": start,
                    "end": end,
                },
            ),
        )

    def get_audit_session_summary(
        self,
        project_id: str,
        session_id: str,
        *,
        start: str | None = None,
        end: str | None = None,
    ) -> AuditSessionSummary:
        """Summarize one agent session.

        Groups a session's audit entries into one deterministic summary: the credentials and origins involved, the window it spans, how many statements were allowed, blocked, masked and truncated, the rows and bytes it moved, and the tables it read, wrote and was refused. No model is involved, so the same entries always summarize the same way. Returns metadata only (table names and counts), never row values, and requires the same audit:read permission the list and export endpoints do.

        ``GET /v1/projects/{project_id}/audit-logs/sessions/{session_id}``

        Args:
            project_id: Unique project identifier (prefixed, e.g. prj_xxx).
            session_id: Session identifier from an audit entry's session_id field. Unique per connection within a proxy instance, not over time.
            start: Return entries at or after this timestamp (inclusive lower bound).
            end: Return entries strictly older than this timestamp (cursor / upper bound).
        """
        return cast(
            AuditSessionSummary,
            self._transport.request(
                "GET",
                "/v1/projects/{project_id}/audit-logs/sessions/{session_id}",
                path_params={
                    "project_id": project_id,
                    "session_id": session_id,
                },
                query={
                    "start": start,
                    "end": end,
                },
            ),
        )

    def verify_audit_chain(
        self,
        project_id: str,
        *,
        start: str | None = None,
        end: str | None = None,
    ) -> AuditChainVerification:
        """Verify the tamper-evident audit chain.

        Recomputes the project's audit hash chain over an optional time range and reports whether it is intact. Each audit entry is linked to its predecessor with a SHA-256 hash, so editing or deleting any row breaks the chain. On a break, the response reports the first sequence number where a tampered or deleted entry was detected. Requires the same audit:read permission as the list and export endpoints.

        ``GET /v1/projects/{project_id}/audit-logs/verify``

        Args:
            project_id: Unique project identifier (prefixed, e.g. prj_xxx).
            start: Return entries at or after this timestamp (inclusive lower bound).
            end: Return entries strictly older than this timestamp (cursor / upper bound).
        """
        return cast(
            AuditChainVerification,
            self._transport.request(
                "GET",
                "/v1/projects/{project_id}/audit-logs/verify",
                path_params={
                    "project_id": project_id,
                },
                query={
                    "start": start,
                    "end": end,
                },
            ),
        )

    def get_agent_usage_breakdown(
        self,
        project_id: str,
        *,
        start: str | None = None,
        end: str | None = None,
    ) -> AgentUsageReport:
        """Break down project usage by agent credential.

        Aggregates the audit trail into per-agent usage for a window: statements by decision, rows and bytes returned, the cache outcome breakdown, and latency percentiles. Read-only, derived entirely from entries the gateway already records. Grouped by credential, not by session. `session_id` is 32 bits of randomness minted per connection, so it identifies a connection rather than an agent or a run, and at scale it collides; the credential is the only stable identity in the trail. This endpoint reports usage and deliberately attributes no dollar figure to an agent. Overage is computed on the organization's total against a plan limit, so no single agent causes it independently of the others, and any per-agent split of that bill is a policy choice rather than a measurement. The organization's limits and marginal rates are returned alongside the usage so a caller can apply its own policy, with both meanings of a zero limit already resolved. Three things are reported rather than assumed. Usage recorded against no credential is its own line, so agents plus unattributed equals totals exactly. Latency covers only entries that ran and carried a finite value: every refusal writes a literal zero because there was nothing to time, and counting those would drag an agent's percentiles toward zero in proportion to how often it was refused, so the heavily blocked agent would report the fastest queries. And gap markers left by undelivered entries set `complete` to false, since a total over a trail with holes in it is a floor, not a measurement. Both `start` and `end` are optional. Omitting `end` means now; omitting `start` means 30 days before the end. The window is half-open and is capped at 92 days, because this aggregate reads every row in the window on the request path and an unbounded one would sort a year of latencies per group. `requested_start` and `requested_end` echo the window that was actually used, so a caller that pinned neither still knows what the totals cover.

        ``GET /v1/projects/{project_id}/usage/agents``

        Args:
            project_id: Unique project identifier (prefixed, e.g. prj_xxx).
            start: Return entries at or after this timestamp (inclusive lower bound).
            end: Return entries strictly older than this timestamp (cursor / upper bound).
        """
        return cast(
            AgentUsageReport,
            self._transport.request(
                "GET",
                "/v1/projects/{project_id}/usage/agents",
                path_params={
                    "project_id": project_id,
                },
                query={
                    "start": start,
                    "end": end,
                },
            ),
        )


