class BatchService:
    """The Batch operations, blocking. Reached as ``client.batch``."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def execute_batch(
        self,
        project_id: str,
        *,
        body: BatchRequest,
    ) -> BatchResponse:
        """Apply many project operations in one request.

        Applies up to 100 project-scoped operations in a single request, so an agent acting on many resources does not have to loop one call at a time. The loops this exists for are the ones the single-resource endpoints leave an operator running by hand: revoking or disabling every agent credential during an incident, triaging a burst of anomaly alerts, and importing the column descriptions for a whole schema. The operation set is closed. A batch is not a tunnel for arbitrary requests; each kind it can perform is named in the contract, carries its own permission, and is authorized independently against the caller's scope before any of them runs, so a batch can never act outside the scope the caller already had. Every operation targets the project in the path, and an id belonging to another project is reported exactly as a nonexistent one is, so this cannot be used to probe for resources the caller cannot see. `mode` is required and decides what a failure means. `atomic` runs the whole batch in one transaction: the first runtime failure rolls it back, the response is 409, and every operation that did not itself fail is reported `not_applied`. `independent` applies each operation on its own and answers 200 with a per-operation status, so a caller can retry exactly the failures. Structural problems (an unknown operation kind, a missing field, a duplicate target) are all found before any work happens and are answered with a single 400. A batch costs the rate limiter one unit per operation, not one per HTTP request, so it is exactly as expensive as the loop it replaces and cannot be used to sidestep the quota. When the remaining quota cannot cover the whole batch the response is 429 and nothing runs, which is a better answer than a loop that discovers the same thing halfway through. A batch refused this way still costs the one unit any request costs, so an oversized batch is not a free way to probe the quota.

        ``POST /v1/projects/{project_id}/batch``

        Args:
            project_id: Unique project identifier (prefixed, e.g. prj_xxx).
            body: The request body.
        """
        return cast(
            BatchResponse,
            self._transport.request(
                "POST",
                "/v1/projects/{project_id}/batch",
                path_params={
                    "project_id": project_id,
                },
                body=body,
            ),
        )


class DemoService:
    """The Demo operations, blocking. Reached as ``client.demo``."""

    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def get_demo(
        self,
    ) -> DemoInfo:
        """Describe the demo sandbox.

        Returns everything an unauthenticated caller needs before asking for a demo credential: whether the demo is up, how much of the global ceiling is left, what each tier costs, the dataset schema with the treatment the demo policy applies to every column, and the walkthrough of statements that demonstrate each guardrail. Requires no account and no key.

        ``GET /v1/demo``
        """
        return cast(
            DemoInfo,
            self._transport.request(
                "GET",
                "/v1/demo",
            ),
        )

    def create_demo_credential(
        self,
        *,
        body: CreateDemoCredentialRequest | None = None,
    ) -> DemoCredential:
        """Issue a demo credential.

        Issues a scoped, read-only, short-lived PostgreSQL credential plus a hosted MCP token against PgBeam's own demo database, with no account and no key. The credential is governed by the same wire-protocol policy engine every customer credential runs through, so a SELECT of a PII column comes back masked, a statement naming the table left off the allowlist is blocked, and a write is refused, all with machine-readable reasons. The connection string and MCP token are shown once. The response also carries the policy document that governed the demo, so a caller who then opens an account can create the same policy on its own database verbatim. Refusals are distinct on purpose. 429 means this client has asked for too many credentials in the last hour and should wait. 503 with a Retry-After header means the global ceiling on concurrent demo credentials is full, so backing off individually will not help; the header says when the oldest session expires. 503 also covers a deployment with no demo database configured.

        ``POST /v1/demo/credentials``

        Args:
            body: The request body.
        """
        return cast(
            DemoCredential,
            self._transport.request(
                "POST",
                "/v1/demo/credentials",
                body=body,
            ),
        )

    def release_demo_credential(
        self,
        session_id: str,
        *,
        body: ReleaseDemoCredentialRequest,
    ) -> DemoReleaseResult:
        """Release a demo credential.

        Revokes a demo credential before its TTL runs out and returns its slot to the global ceiling. Callers that finish early should do this so the next evaluating agent is not turned away by a session nobody is using. The MCP token issued with the credential proves the caller holds it. Releasing an already-expired or already-released session succeeds with released=false.

        ``POST /v1/demo/credentials/{session_id}/release``

        Args:
            session_id: The demo session to release, as returned when it was issued.
            body: The request body.
        """
        return cast(
            DemoReleaseResult,
            self._transport.request(
                "POST",
                "/v1/demo/credentials/{session_id}/release",
                path_params={
                    "session_id": session_id,
                },
                body=body,
            ),
        )


