    async def list_self_host_enrollments(
        self,
        org_id: str,
        *,
        page_size: int | None = None,
        page_token: str | None = None,
    ) -> ListSelfHostEnrollmentsResponse:
        """List self-host enrollments.

        Lists an organization's self-host enrollments. Tokens are never returned.

        ``GET /v1/organizations/{org_id}/self-host-enrollments``

        Args:
            org_id: Unique organization identifier.
            page_size: Maximum number of items to return (1-100, default 20).
            page_token: Opaque token for cursor-based pagination.
        """
        return cast(
            ListSelfHostEnrollmentsResponse,
            await self._transport.request(
                "GET",
                "/v1/organizations/{org_id}/self-host-enrollments",
                path_params={
                    "org_id": org_id,
                },
                query={
                    "page_size": page_size,
                    "page_token": page_token,
                },
            ),
        )

    async def create_self_host_enrollment(
        self,
        org_id: str,
        *,
        body: CreateSelfHostEnrollmentRequest | None = None,
    ) -> SelfHostEnrollmentSecret:
        """Issue a self-host enrollment token.

        Issues an enrollment token a self-hosted (BYOC) proxy uses to authenticate to the control plane's config/audit gRPC stream. The token is returned once and cannot be retrieved again. Requires the Scale or enterprise plan.

        ``POST /v1/organizations/{org_id}/self-host-enrollments``

        Args:
            org_id: Unique organization identifier.
            body: The request body.
        """
        return cast(
            SelfHostEnrollmentSecret,
            await self._transport.request(
                "POST",
                "/v1/organizations/{org_id}/self-host-enrollments",
                path_params={
                    "org_id": org_id,
                },
                body=body,
            ),
        )

    async def revoke_self_host_enrollment(
        self,
        org_id: str,
        enrollment_id: str,
    ) -> None:
        """Revoke a self-host enrollment.

        Revokes an enrollment so its token can no longer authenticate a proxy. Connected proxies keep their last-known config until they reconnect.

        ``DELETE /v1/organizations/{org_id}/self-host-enrollments/{enrollment_id}``

        Args:
            org_id: Unique organization identifier.
            enrollment_id: Unique enrollment identifier.
        """
        await self._transport.request(
            "DELETE",
            "/v1/organizations/{org_id}/self-host-enrollments/{enrollment_id}",
            path_params={
                "org_id": org_id,
                "enrollment_id": enrollment_id,
            },
        )
        return None

    async def rotate_self_host_enrollment(
        self,
        org_id: str,
        enrollment_id: str,
    ) -> SelfHostEnrollmentSecret:
        """Rotate a self-host enrollment token.

        Mints a new enrollment token in place, keeping the same enrollment id, metadata, and expiry. The swap is atomic: the old token stops authenticating new proxy connections the moment this call returns. An already-connected proxy keeps its existing gRPC streams until it disconnects, then must present the new token to reconnect. The new token is returned once and cannot be retrieved again.

        ``POST /v1/organizations/{org_id}/self-host-enrollments/{enrollment_id}/rotate``

        Args:
            org_id: Unique organization identifier.
            enrollment_id: Unique enrollment identifier.
        """
        return cast(
            SelfHostEnrollmentSecret,
            await self._transport.request(
                "POST",
                "/v1/organizations/{org_id}/self-host-enrollments/{enrollment_id}/rotate",
                path_params={
                    "org_id": org_id,
                    "enrollment_id": enrollment_id,
                },
            ),
        )

    async def scan_text(
        self,
        *,
        body: ScanTextRequest,
    ) -> ScanTextResult:
        """Scan untrusted text for prompt injection.

        Inspects one piece of untrusted text for the techniques used to smuggle instructions into a model's context, and returns a verdict, a recommended action, and the evidence behind it. Two detector families run. The structural layer reads codepoints and scripts: invisible-codepoint runs, Unicode Tag smuggling, unterminated bidirectional overrides, and mixed-script words. None of those has a legitimate reason to appear in ordinary text, so a structural finding is a fact worth acting on. The lexical layer is exact-phrase matching with Unicode normalization, which is worth what exact-phrase matching is worth: it is a reason to look, and a support ticket quoting an attack contains the attack. Neither layer is a semantic classifier, and this endpoint does not pretend to catch prose that is hostile only in its meaning. The measured confusion matrix and the list of evasions that are known to work are published at https://pgbeam.com/docs/prompt-scan. Authentication is optional. Anonymous callers get a free daily allowance keyed on their source address; an API key moves the allowance onto the organization. Past the allowance the endpoint answers 402 with a payment challenge. The submitted text is held in memory for the duration of the request and is never logged, stored, or used to train anything. An `Idempotency-Key` is refused on this operation rather than honoured, because honouring it would persist the response, and the response quotes the submitted text back. The operation has no side effects beyond metering, so a retry is safe without one.

        ``POST /v1/scan/text``

        Args:
            body: The request body.
        """
        return cast(
            ScanTextResult,
            await self._transport.request(
                "POST",
                "/v1/scan/text",
                body=body,
            ),
        )


