class AsyncPaymentsService:
    """The Payments operations, awaitable. Reached as ``client.payments``."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._transport = transport

    async def list_payment_resources(
        self,
    ) -> ListPaymentResourcesResponse:
        """List priced resources.

        Lists what an agent can buy over the Machine Payments Protocol, with the unit, the pack size, and the price of one pack. Discovery only: the `WWW-Authenticate: Payment` challenge returned by a priced operation is always authoritative. This endpoint takes no authentication so an agent can read the price before it holds a credential.

        ``GET /v1/payments/resources``
        """
        return cast(
            ListPaymentResourcesResponse,
            await self._transport.request(
                "GET",
                "/v1/payments/resources",
            ),
        )

    async def create_budget_topup(
        self,
        *,
        body: BudgetTopupInput | None = None,
    ) -> BudgetTopup:
        """Buy query budget for an agent credential.

        Buys additional queries for the agent credential this request is authenticated as, using the Machine Payments Protocol (HTTP 402 with the `Payment` authentication scheme). Authenticate with the credential's hosted MCP token (`pba_...`) as a bearer token. The credential identifies itself, so no human and no dashboard session is involved. Without a payment credential the response is `402` carrying a complete `WWW-Authenticate: Payment` challenge. Fulfil it, then repeat the request with the credential in the `Payment-Authorization` header (the challenge selects that field so the bearer token can stay in `Authorization`). On success the queries are granted, streamed to the data planes, and the response carries a `Payment-Receipt` header. Purchased queries do not raise the credential's policy budget. They are a separate pool the proxy spends only once the policy's hourly and daily windows have refused a statement, and they expire.

        ``POST /v1/payments/budget-topups``

        Args:
            body: The request body.
        """
        return cast(
            BudgetTopup,
            await self._transport.request(
                "POST",
                "/v1/payments/budget-topups",
                body=body,
            ),
        )


class PgBeamClient(BaseClient):
    """The blocking PgBeam API client.

    Construction, authentication, retries and shutdown are described on
    ``BaseClient``. This class adds one attribute per API tag.

    Example:
        with PgBeamClient(token="...") as client:
            projects = client.projects.list_projects(org_id="org_123")
    """

    projects: ProjectsService
    databases: DatabasesService
    policies: PoliciesService
    agents: AgentsService
    approvals: ApprovalsService
    webhooks: WebhooksService
    honeytokens: HoneytokensService
    schema_annotations: SchemaAnnotationsService
    anomalies: AnomaliesService
    branches: BranchesService
    migrations: MigrationsService
    analytics: AnalyticsService
    platform: PlatformService
    account: AccountService
    support: SupportService
    batch: BatchService
    demo: DemoService
    internal: InternalService
    payments: PaymentsService

    def _bind_services(self) -> None:
        self.projects = ProjectsService(self._transport)
        self.databases = DatabasesService(self._transport)
        self.policies = PoliciesService(self._transport)
        self.agents = AgentsService(self._transport)
        self.approvals = ApprovalsService(self._transport)
        self.webhooks = WebhooksService(self._transport)
        self.honeytokens = HoneytokensService(self._transport)
        self.schema_annotations = SchemaAnnotationsService(self._transport)
        self.anomalies = AnomaliesService(self._transport)
        self.branches = BranchesService(self._transport)
        self.migrations = MigrationsService(self._transport)
        self.analytics = AnalyticsService(self._transport)
        self.platform = PlatformService(self._transport)
        self.account = AccountService(self._transport)
        self.support = SupportService(self._transport)
        self.batch = BatchService(self._transport)
        self.demo = DemoService(self._transport)
        self.internal = InternalService(self._transport)
        self.payments = PaymentsService(self._transport)


